pub fn sf1_shape_metrics(shape_id: u16) -> Option<Sf1ShapeMetrics> {
    SF1_SHAPE_METRICS
        .binary_search_by_key(&shape_id, |&(id, _)| id)
        .ok()
        .map(|index| SF1_SHAPE_METRICS[index].1)
}
